import { Locator, Page } from '@playwright/test';

export class LoginPage {
  readonly title: Locator;
  readonly emailInput: Locator;
  readonly passwordInput: Locator;
  readonly loginButton: Locator;
  readonly errorMessage: Locator;

  constructor(private readonly page: Page) {
    this.title = page.getByRole('heading', { name: 'Login', level: 1 });
    this.emailInput = page.getByRole('textbox', { name: 'Text field for the login email' });
    this.passwordInput = page.getByRole('textbox', { name: 'Text field for the login password' });
    this.loginButton = page.getByRole('button', { name: 'Login', exact: true });
    this.errorMessage = page.locator('app-login .error');
  }

  async open(): Promise<void> {
    await this.page.goto('/#/login');
    await this.title.waitFor();
  }

  async submit(email: string, password: string): Promise<void> {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }

  /** Logs in through the UI and waits for the product list. */
  async login(email: string, password: string): Promise<void> {
    await this.open();
    await this.submit(email, password);
    await this.page.waitForURL(/#\/search/);
  }
}

