import { test, expect } from './support/fixtures';

test('TC-01: Login with a valid and an invalid password', async ({ page, customer, loginPage, navBar }) => {
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await loginPage.open();
    await expect(loginPage.title).toHaveText('Login');
    await expect(page.getByText('Email', { exact: true })).toBeVisible();
    await expect(loginPage.emailInput).toBeVisible();
    await expect(page.getByText('Password', { exact: true })).toBeVisible();
    await expect(loginPage.passwordInput).toBeVisible();
    await expect(loginPage.loginButton).toHaveText(/Log in/);
  });

  await test.step('2. Log in with the wrong password', async () => {
    await loginPage.submit(customer.email, wrongPassword);
    await expect(loginPage.errorMessage).toHaveText('Invalid email or password.');
    await expect(page).toHaveURL(/#\/login/);
    await expect(loginPage.title).toBeVisible();
  });

  await test.step('3. The account menu shows Login and no email', async () => {
    await navBar.openAccountMenu();
    await expect(navBar.loginMenuItem).toBeVisible();
    await expect(navBar.loginMenuItem).toHaveText(/Login/);
    await expect(navBar.accountMenu).not.toContainText(customer.email);
    await expect(navBar.logoutMenuItem).toBeHidden();
  });

  await test.step('4. Close the menu and log in with the correct password', async () => {
    await navBar.closeMenu();
    await loginPage.submit(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search/);
  });

  await test.step('5. The account menu shows the email and Logout', async () => {
    await navBar.openAccountMenu();
    await expect(navBar.accountMenu).toContainText(customer.email);
    await expect(navBar.logoutMenuItem).toBeVisible();
    await expect(navBar.loginMenuItem).toBeHidden();
  });
});

