import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { PRODUCTS, priceText } from './support/test-data';

test('TC-02: Add a product to the basket', async ({ page, loggedInCustomer: _, productList, navBar, basket }) => {
  const product = PRODUCTS.eggfruitJuice;

  await test.step('1. Open the product list', async () => {
    await productList.open();
    await expect(productList.productName(product.name)).toHaveText(product.name);
    await expect(productList.productPrice(product.name)).toHaveText(priceText(product.price));
    await expect(productList.addToBasketButton(product.name)).toBeVisible();
    await expect(navBar.basketCounter).toHaveText('0');
  });

  await test.step('2. Add the product to the basket', async () => {
    await productList.addToBasket(product.name);
    await expect(productList.message(`Placed ${product.name} into basket.`).first()).toBeVisible();
    await expect(navBar.basketCounter).toHaveText('1');
  });

  await test.step('3. Open the basket', async () => {
    await navBar.openBasket();
    await basket.waitForLoad();
    await expect(page).toHaveURL(/#\/basket/);
    await expect(basket.rows).toHaveCount(1);
    await expect(basket.row(product.name)).toBeVisible();
    await expect(basket.quantity(product.name)).toHaveText('1');
    await expect(basket.price(product.name)).toHaveText(priceText(product.price));
  });

  await test.step('4. Read the total of the basket', async () => {
    await expectPrice(basket.totalPrice, product.price);
  });
});

