import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { addSavedAddressAndCard } from './support/checkout';
import { ADDRESS, CARD_LAST_DIGITS, DELIVERY, PRODUCTS, couponCode, money, priceText } from './support/test-data';

test('TC-05: Valid coupon on the payment step', async ({
  loggedInCustomer,
  basket,
  selectAddress,
  deliveryMethod,
  payment,
  orderSummary,
}) => {
  const product = PRODUCTS.eggfruitJuice;
  const quantity = 2;
  const discountPercent = 10;
  const coupon = couponCode(discountPercent);

  await addSavedAddressAndCard(loggedInCustomer);
  await loggedInCustomer.api.addToBasket(product.name, quantity);

  const items = money(product.price * quantity);
  const promotion = money((items * discountPercent) / 100);
  const total = money(items + DELIVERY.oneDay.price - promotion);

  await test.step('1. Open the basket and click Checkout', async () => {
    await basket.open();
    await basket.checkout();
    await expect(selectAddress.title).toBeVisible();
    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.fullName);
    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.streetAddress);
    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.country);
  });

  await test.step('2. Select the saved address and continue', async () => {
    await selectAddress.selectSavedAddressAndContinue();
    await expect(deliveryMethod.title).toBeVisible();
    for (const option of [DELIVERY.oneDay, DELIVERY.fast, DELIVERY.standard]) {
      await expect(deliveryMethod.option(option.name)).toBeVisible();
      await expect(deliveryMethod.optionPrice(option.name)).toHaveText(priceText(option.price));
    }
  });

  await test.step('3. Select One Day Delivery and continue', async () => {
    await deliveryMethod.selectAndContinue(DELIVERY.oneDay.name);
    await expect(payment.title).toBeVisible();
    await expect(payment.savedCardRow).toContainText(CARD_LAST_DIGITS);
    await expect(payment.couponPanelButton).toBeVisible();
  });

  await test.step('4. Redeem the coupon of the current month', async () => {
