import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { addSavedAddressAndCard } from './support/checkout';
import { ADDRESS, CARD, CARD_LAST_DIGITS, DELIVERY, PRODUCTS, couponCode, itemsTotal, money } from './support/test-data';

test('TC-07: Order with a card, from basket to order history', async ({
  loggedInCustomer,
  page,
  productList,
  navBar,
  basket,
  selectAddress,
  deliveryMethod,
  payment,
  orderSummary,
  orderCompletion,
  orderHistory,
}) => {
  const a = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
  const b = { product: PRODUCTS.carrotJuice, quantity: 1 };
  const discountPercent = 10;
  const coupon = couponCode(discountPercent);

  await addSavedAddressAndCard(loggedInCustomer);

  const items = itemsTotal([a, b]);
  const promotion = money((items * discountPercent) / 100);
  const total = money(items + DELIVERY.oneDay.price - promotion);
  let orderId = '';

  await test.step('1. Add product A two times and product B one time', async () => {
    await productList.open();
    await productList.addToBasket(a.product.name);
    await expect(navBar.basketCounter).toHaveText('1');
    await productList.addToBasket(a.product.name);
    await expect(navBar.basketCounter).toHaveText('2');
    await productList.addToBasket(b.product.name);
    await expect(navBar.basketCounter).toHaveText(String(a.quantity + b.quantity));
  });

  await test.step('2. Open the basket', async () => {
    await basket.open();
    await expect(basket.rows).toHaveCount(2);
    await expect(basket.quantity(a.product.name)).toHaveText(String(a.quantity));
    await expect(basket.quantity(b.product.name)).toHaveText(String(b.quantity));
    await expectPrice(basket.totalPrice, items);
  });

  await test.step('3. Checkout with the saved address', async () => {
    await basket.checkout();
    await selectAddress.selectSavedAddressAndContinue();
    await expect(deliveryMethod.title).toBeVisible();
  });

  await test.step('4. Select One Day Delivery and continue', async () => {
    await deliveryMethod.selectAndContinue(DELIVERY.oneDay.name);
    await expect(payment.title).toBeVisible();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await payment.openCouponPanel();
    await payment.redeemCoupon(coupon);
    await expect(payment.couponConfirmation).toHaveText(
      `Your discount of ${discountPercent}% will be applied during checkout.`,
    );
  });

  await test.step('6. Select the saved card and continue to the order summary', async () => {
    await payment.selectSavedCardAndContinue();
    await orderSummary.waitForLoad();
    await expect(orderSummary.deliveryAddress).toContainText(ADDRESS.fullName);
    await expect(orderSummary.deliveryAddress).toContainText(
      `${ADDRESS.streetAddress}, ${ADDRESS.city}, ${ADDRESS.state}, ${ADDRESS.zipCode}`,
    );
    await expect(orderSummary.deliveryAddress).toContainText(ADDRESS.country);
    await expect(orderSummary.paymentMethod).toContainText(`Card ending in ${CARD_LAST_DIGITS}`);
    await expect(orderSummary.paymentMethod).toContainText(CARD.fullName);
    await expect(orderSummary.basketRows).toHaveCount(2);
    await expect(orderSummary.row(a.product.name)).toContainText(String(a.quantity));
    await expect(orderSummary.row(b.product.name)).toContainText(String(b.quantity));
    await expectPrice(orderSummary.totals.items, items);
    await expectPrice(orderSummary.totals.delivery, DELIVERY.oneDay.price);
    await expectPrice(orderSummary.totals.promotion, promotion);
    await expectPrice(orderSummary.totals.total, total);
  });

  await test.step('7. Place the order', async () => {
    orderId = await orderSummary.placeOrder();
    expect(orderId).not.toBe('');
    await expect(page).toHaveURL(new RegExp(`#/order-completion/${orderId}$`));
    await expect(orderCompletion.title).toBeVisible();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await expect(orderCompletion.productRow(a.product.name)).toContainText(` ${a.quantity} `);
    await expect(orderCompletion.productRow(b.product.name)).toContainText(` ${b.quantity} `);
    await expect.poll(() => orderCompletion.totals()).toEqual({
      items,
      delivery: DELIVERY.oneDay.price,
      promotion,
      total,
    });
  });

  await test.step('9. The basket is empty', async () => {
    await expect(navBar.basketCounter).toHaveText('0');
    await basket.open();
    await expect(basket.rows).toHaveCount(0);
    await expect(basket.checkoutButton).toBeDisabled();
  });

  await test.step('10. Open the order history', async () => {
    await navBar.openOrderHistory();
    await expect(orderHistory.title).toBeVisible();
    await expect(orderHistory.orders).toHaveCount(1);
    const order = orderHistory.order(orderId);
    await expect(orderHistory.orderField(order, 'Order ID')).toHaveText(`#${orderId}`);
    await expectPrice(orderHistory.orderField(order, 'Total Price'), total);
    await expect(orderHistory.productQuantity(order, a.product.name)).toHaveText(String(a.quantity));
    await expect(orderHistory.productQuantity(order, b.product.name)).toHaveText(String(b.quantity));
  });
});

