import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { addSavedAddressAndCard } from './support/checkout';
import { DELIVERY, PRODUCTS, bonusPoints, money, priceText } from './support/test-data';

test('TC-08: Payment with the wallet', async ({
  loggedInCustomer,
  page,
  navBar,
  basket,
  selectAddress,
  deliveryMethod,
  payment,
  orderSummary,
  orderCompletion,
  orderHistory,
  wallet,
}) => {
  const line = { product: PRODUCTS.eggfruitJuice, quantity: 1 };
  const firstBalance = 5;
  const topUp = 3.99;
  const total = money(line.product.price * line.quantity + DELIVERY.standard.price);
  const bonus = bonusPoints([line]);

  const cardId = await addSavedAddressAndCard(loggedInCustomer);
  await loggedInCustomer.api.addToBasket(line.product.name, line.quantity);
  expect(await loggedInCustomer.api.topUpWallet(firstBalance, cardId)).toBe(firstBalance);

  const goToPayment = async () => {
    await basket.open();
    await basket.checkout();
    await selectAddress.selectSavedAddressAndContinue();
    await expect(deliveryMethod.title).toBeVisible();
    await deliveryMethod.selectAndContinue(DELIVERY.standard.name);
    await expect(payment.title).toBeVisible();
  };

  // Part 1: the wallet holds less than the order total.

  await test.step('1. Checkout with the saved address', async () => {
    await basket.open();
    await basket.checkout();
    await selectAddress.selectSavedAddressAndContinue();
    await expect(deliveryMethod.title).toBeVisible();
  });

  await test.step('2. Select Standard Delivery and continue', async () => {
    await deliveryMethod.selectAndContinue(DELIVERY.standard.name);
    await expect(payment.title).toBeVisible();
    await expectPrice(payment.walletBalance, firstBalance);
    await expect(payment.walletPayButton).toHaveText(new RegExp(`Pay ${priceText(total)}`));
  });

  await test.step(`3. The button Pay ${priceText(total)} is disabled`, async () => {
    await expect(payment.walletPayButton).toBeDisabled();
  });

  await test.step('4. The order history is empty', async () => {
    await navBar.openOrderHistory();
    await expect(orderHistory.emptyMessage).toBeVisible();
    await expect(orderHistory.orders).toHaveCount(0);
  });

  await test.step('5. The wallet balance is unchanged', async () => {
    await navBar.openDigitalWallet();
    await expect(wallet.title).toBeVisible();
    await expectPrice(wallet.balance, firstBalance);
  });

  // Part 2: the wallet holds exactly the order total.
  expect(await loggedInCustomer.api.topUpWallet(topUp, cardId)).toBeCloseTo(firstBalance + topUp, 2);
  const balance = money(firstBalance + topUp);
  expect(balance).toBe(total);

  await test.step('6. Checkout again to the payment options', async () => {
    await goToPayment();
    await expectPrice(payment.walletBalance, balance);
    await expect(payment.walletPayButton).toHaveText(new RegExp(`Pay ${priceText(total)}`));
    await expect(payment.walletPayButton).toBeEnabled();
  });

  await test.step(`7. Click Pay ${priceText(total)}`, async () => {
    await payment.payWithWallet();
    await orderSummary.waitForLoad();
    await expect(orderSummary.paymentMethod).toContainText('Digital Wallet');
    await expectPrice(orderSummary.totals.total, total);
  });

  await test.step('8. Place the order', async () => {
    await orderSummary.placeOrder();
    await expect(page).toHaveURL(/#\/order-completion\/.+/);
    await expect(orderCompletion.title).toBeVisible();
  });

  await test.step('9. The wallet balance is the bonus of the order', async () => {
    await navBar.openDigitalWallet();
    await expectPrice(wallet.balance, balance - total + bonus);
  });

  await test.step('10. The order history shows the order', async () => {
    await navBar.openOrderHistory();
    await expect(orderHistory.orders).toHaveCount(1);
    const order = orderHistory.orders.first();
    await expectPrice(orderHistory.orderField(order, 'Total Price'), total);
    await expect(orderHistory.orderField(order, 'Bonus')).toHaveText(String(bonus));
  });
});

