import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { PRODUCTS } from './support/test-data';

test('TC-03: Change the quantity and remove a product in the basket', async ({
  loggedInCustomer,
  page,
  basket,
  navBar,
}) => {
  const a = PRODUCTS.raspberryJuice;
  const b = PRODUCTS.eggfruitJuice;
  await loggedInCustomer.api.addToBasket(a.name, 1);
  await loggedInCustomer.api.addToBasket(b.name, 1);

  await test.step('1. Open the basket', async () => {
    await basket.open();
    await expect(basket.rows).toHaveCount(2);
    await expect(basket.quantity(a.name)).toHaveText('1');
    await expect(basket.quantity(b.name)).toHaveText('1');
    await expectPrice(basket.totalPrice, a.price + b.price);
    await expect(navBar.basketCounter).toHaveText('2');
  });

  await test.step('2. Click plus in the row of product A', async () => {
    await basket.increase(a.name);
    await expect(basket.quantity(a.name)).toHaveText('2');
    await expectPrice(basket.totalPrice, 2 * a.price + b.price);
    await expect(navBar.basketCounter).toHaveText('3');
  });

  await test.step('3. Click minus in the row of product A', async () => {
    await basket.decrease(a.name);
    await expect(basket.quantity(a.name)).toHaveText('1');
    await expectPrice(basket.totalPrice, a.price + b.price);
    await expect(navBar.basketCounter).toHaveText('2');
  });

  await test.step('4. Click minus in the row of product A again', async () => {
    await basket.decrease(a.name);
    await expect(basket.row(a.name)).toBeVisible();
    await expect(basket.quantity(a.name)).toHaveText('1');
    await expectPrice(basket.totalPrice, a.price + b.price);
    // The quantity must stay 1 also after a reload from the server.
    await page.reload();
    await basket.waitForLoad();
    await expect(basket.row(a.name)).toBeVisible();
    await expect(basket.quantity(a.name)).toHaveText('1');
    await expectPrice(basket.totalPrice, a.price + b.price);
  });

  await test.step('5. Click trash in the row of product A', async () => {
    await basket.remove(a.name);
    await expect(basket.row(a.name)).toHaveCount(0);
    await expect(basket.rows).toHaveCount(1);
    await expect(basket.quantity(b.name)).toHaveText('1');
    await expectPrice(basket.totalPrice, b.price);
    await expect(navBar.basketCounter).toHaveText('1');
  });
});

import { test, expect } from './support/fixtures';
import { expectPrice } from './support/assertions';
import { addSavedAddressAndCard } from './support/checkout';
import { ADDRESS, CARD_LAST_DIGITS, DELIVERY, PRODUCTS, couponCode, money, priceText } from './support/test-data';

test('TC-05: Valid coupon on the payment step', async ({
  loggedInCustomer,
  basket,
  selectAddress,
  deliveryMethod,
  payment,
  orderSummary,
}) => {
  const product = PRODUCTS.eggfruitJuice;
  const quantity = 2;
  const discountPercent = 10;
  const coupon = couponCode(discountPercent);

  await addSavedAddressAndCard(loggedInCustomer);
  await loggedInCustomer.api.addToBasket(product.name, quantity);

  const items = money(product.price * quantity);
  const promotion = money((items * discountPercent) / 100);
  const total = money(items + DELIVERY.oneDay.price - promotion);

  await test.step('1. Open the basket and click Checkout', async () => {
    await basket.open();
    await basket.checkout();
    await expect(selectAddress.title).toBeVisible();
    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.fullName);
    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.streetAddress);
    await expect(selectAddress.savedAddressRow).toContainText(ADDRESS.country);
  });

  await test.step('2. Select the saved address and continue', async () => {
    await selectAddress.selectSavedAddressAndContinue();
    await expect(deliveryMethod.title).toBeVisible();
    for (const option of [DELIVERY.oneDay, DELIVERY.fast, DELIVERY.standard]) {
      await expect(deliveryMethod.option(option.name)).toBeVisible();
      await expect(deliveryMethod.optionPrice(option.name)).toHaveText(priceText(option.price));
    }
  });

  await test.step('3. Select One Day Delivery and continue', async () => {
    await deliveryMethod.selectAndContinue(DELIVERY.oneDay.name);
    await expect(payment.title).toBeVisible();
    await expect(payment.savedCardRow).toContainText(CARD_LAST_DIGITS);
    await expect(payment.couponPanelButton).toBeVisible();
  });

  await test.step('4. Redeem the coupon of the current month', async () => {
    await payment.openCouponPanel();
    await payment.redeemCoupon(coupon);
    await expect(payment.couponConfirmation).toHaveText(
      `Your discount of ${discountPercent}% will be applied during checkout.`,
    );
    await expect(payment.couponError).toHaveCount(0);
  });

  await test.step('5. Select the saved card and continue', async () => {
    await payment.selectSavedCardAndContinue();
    await orderSummary.waitForLoad();
    await expect(orderSummary.row(product.name)).toContainText(String(quantity));
    await expectPrice(orderSummary.totals.items, items);
    await expectPrice(orderSummary.totals.delivery, DELIVERY.oneDay.price);
    await expectPrice(orderSummary.totals.promotion, promotion);
    await expectPrice(orderSummary.totals.total, total);
  });
});

